// Schema "agent" of docs/architecture.md section 4.3: conversations, chat_sessions, messages, llm_calls.
// Owned by Dev 2 (apps/agent), reviewed by Dev 3. The agent never reads or writes the core schema.
import { sql } from 'drizzle-orm';
import {
  boolean,
  check,
  customType,
  index,
  integer,
  jsonb,
  pgSchema,
  text,
  timestamp,
  unique,
  uuid,
} from 'drizzle-orm/pg-core';
import { uuidv7 } from 'uuidv7';

export const agentSchema = pgSchema('agent');

// Same conventions as the core schema: ids generated by the application (PGlite has no uuidv7()),
// and bytea always handed out as a Buffer (PGlite returns a Uint8Array).
const bytea = customType<{ data: Buffer; driverData: Uint8Array }>({
  dataType: () => 'bytea',
  fromDriver: (v) => Buffer.from(v),
});

const id = () =>
  uuid('id')
    .primaryKey()
    .$defaultFn(() => uuidv7());
const createdAt = () => timestamp('created_at', { withTimezone: true }).notNull().defaultNow();

export const conversations = agentSchema.table(
  'conversations',
  {
    id: id(),
    vendorId: uuid('vendor_id').notNull(), // core.vendors.id; no cross-schema foreign key on purpose
    channel: text('channel', { enum: ['web', 'whatsapp', 'instagram'] })
      .notNull()
      .default('web'),
    role: text('role', { enum: ['customer', 'vendor'] }).notNull(),
    externalUserId: text('external_user_id').notNull(),
    customerId: uuid('customer_id'),
    customerLabel: text('customer_label'),
    mode: text('mode', { enum: ['bot', 'human', 'paused'] })
      .notNull()
      .default('bot'),
    humanUntil: timestamp('human_until', { withTimezone: true }),
    vendorReadAt: timestamp('vendor_read_at', { withTimezone: true }),
    lastInboundAt: timestamp('last_inbound_at', { withTimezone: true }),
    language: text('language'),
    summary: text('summary').notNull().default(''),
    state: jsonb('state').$type<Record<string, unknown>>().notNull().default({}),
    createdAt: createdAt(),
    updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    unique('conversations_vendor_channel_user').on(t.vendorId, t.channel, t.externalUserId),
    check('conversations_channel', sql`${t.channel} in ('web', 'whatsapp', 'instagram')`),
    check('conversations_role', sql`${t.role} in ('customer', 'vendor')`),
    check('conversations_mode', sql`${t.mode} in ('bot', 'human', 'paused')`),
  ],
);

export const chatSessions = agentSchema.table('chat_sessions', {
  id: id(),
  vendorId: uuid('vendor_id').notNull(),
  conversationId: uuid('conversation_id')
    .notNull()
    .references(() => conversations.id),
  tokenHash: bytea('token_hash').notNull().unique(),
  ipHash: bytea('ip_hash'),
  expiresAt: timestamp('expires_at', { withTimezone: true }).notNull(),
  lastSeenAt: timestamp('last_seen_at', { withTimezone: true }).notNull().defaultNow(),
  createdAt: createdAt(),
});

export const messages = agentSchema.table(
  'messages',
  {
    id: id(),
    conversationId: uuid('conversation_id')
      .notNull()
      .references(() => conversations.id),
    direction: text('direction', { enum: ['in', 'out'] }).notNull(),
    author: text('author', { enum: ['customer', 'vendor', 'agent', 'system'] }).notNull(),
    authorLabel: text('author_label'),
    kind: text('kind', { enum: ['text', 'audio', 'image', 'order_link', 'system'] }).notNull(),
    text: text('text'),
    cards: jsonb('cards').$type<unknown[]>().notNull().default([]),
    quickReplies: jsonb('quick_replies')
      .$type<{ id: string; label: string }[]>()
      .notNull()
      .default([]),
    mediaKey: text('media_key'),
    imageKeys: jsonb('image_keys').$type<string[]>().notNull().default([]),
    quickReplyId: text('quick_reply_id'),
    clientMessageId: text('client_message_id'),
    status: text('status', { enum: ['accepted', 'processed', 'failed'] }),
    createdAt: createdAt(),
  },
  (t) => [
    unique('messages_conversation_client_id').on(t.conversationId, t.clientMessageId),
    index('messages_by_conversation').on(t.conversationId, t.id),
    check('messages_direction', sql`${t.direction} in ('in', 'out')`),
    check('messages_author', sql`${t.author} in ('customer', 'vendor', 'agent', 'system')`),
    check('messages_kind', sql`${t.kind} in ('text', 'audio', 'image', 'order_link', 'system')`),
    check('messages_status', sql`${t.status} in ('accepted', 'processed', 'failed')`),
  ],
);

export const llmCalls = agentSchema.table('llm_calls', {
  id: id(),
  conversationId: uuid('conversation_id'),
  vendorId: uuid('vendor_id'),
  purpose: text('purpose').notNull(), // reply, summary, extraction, transcription
  model: text('model').notNull(),
  latencyMs: integer('latency_ms'),
  inputTokens: integer('input_tokens'),
  outputTokens: integer('output_tokens'),
  toolCalls: jsonb('tool_calls'),
  error: text('error'),
  createdAt: createdAt(),
});

/** Core events already handled, so a redelivery from the outbox is acknowledged as a duplicate. */
export const processedEvents = agentSchema.table('processed_events', {
  eventId: uuid('event_id').primaryKey(),
  type: text('type').notNull(),
  receivedAt: timestamp('received_at', { withTimezone: true }).notNull().defaultNow(),
});

/** Per-vendor agent switches that must survive a restart and be shared by every agent instance. */
export const vendorSettings = agentSchema.table('vendor_settings', {
  vendorId: uuid('vendor_id').primaryKey(),
  // "Pause all chats" from the vendor assistant: paused when set; null `bot_paused_until` means until resumed.
  botPaused: boolean('bot_paused').notNull().default(false),
  botPausedUntil: timestamp('bot_paused_until', { withTimezone: true }),
  updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
});
